import axios from "axios";
import logo from "../assets/logo.png";
import search from "../assets/search.png";
import gps from "../assets/gps.png";
import restrologo from "../assets/restrologo.png";
import delivery from "../assets/delivery.jpg";
import dining from "../assets/dining.jpg";
import biryani from "../assets/biryani.png";
import burger from "../assets/burger.png";
import thali from "../assets/thali.png";
import food from "../assets/food.png";
import foodimage from "../assets/foodimage.png";
import restaurant from "../assets/restaurant.png";
import picture from "../assets/picture.png";

// ✅ URLs
const LOCAL = "http://localhost:5000";
const LIVE = process.env.REACT_APP_API_URL;

// ✅ Auto switch (local dev vs production)
const serverURL =
  window.location.hostname === "localhost" ? LOCAL : LIVE;

const localImageMap = {
  "headerlogo.png": logo,
  "search.png": search,
  "gps.png": gps,
  "restrologo.png": restrologo,
  "online.jpg": delivery,
  "dining.jpg": dining,
  "foodpic.png": foodimage,
  "veg.png": "/veg.png",
  "nonveg.png": "/nonveg.png",
};

const keywordFallbacks = [
  { keywords: ["biryani", "rice", "pulao"], image: biryani },
  { keywords: ["burger", "sandwich", "wrap", "pizza", "roll"], image: burger },
  { keywords: ["thali", "meal", "combo", "paneer", "veg"], image: thali },
  { keywords: ["sweet", "dessert", "cake", "pastry", "mithai"], image: picture },
  { keywords: ["delivery", "online", "order"], image: delivery },
  { keywords: ["dining", "nightlife"], image: dining },
  { keywords: ["restaurant", "cafe", "dhaba", "hotel", "brand"], image: restaurant },
];

function normalizeImageName(imageName) {
  if (!imageName) return "";
  return String(imageName).trim().replace(/^,+|,+$/g, "");
}

function getImageList(imageValue) {
  return String(imageValue || "")
    .split(",")
    .map((item) => normalizeImageName(item))
    .filter(Boolean);
}

function pickImageName(imageValue, preferredIndex = 0) {
  const imageList = getImageList(imageValue);
  return imageList[preferredIndex] || imageList[0] || "";
}

function encodeImagePath(imageName) {
  return imageName
    .split("/")
    .map((part) => encodeURIComponent(part.trim()))
    .join("/");
}

function getFallbackImage(...fallbackHints) {
  const hintText = fallbackHints
    .filter(Boolean)
    .join(" ")
    .toLowerCase();

  const matchedImage = keywordFallbacks.find(({ keywords }) =>
    keywords.some((keyword) => hintText.includes(keyword))
  );

  return matchedImage?.image || food || picture;
}

// ✅ OTP Generator
function generateOtp() {
  return Math.floor(Math.random() * 900000) + 100000;
}

// ✅ GET API
async function getData(url) {
  try {
    const response = await axios.get(`${serverURL}/${url}`);
    return response.data;
  } catch (e) {
    console.error("GET ERROR:", e.message);

    return {
      data: [],
      message: "Server error, please try again...",
      status: false,
    };
  }
}

// ✅ POST API
async function postData(url, body) {
  try {
    const response = await axios.post(`${serverURL}/${url}`, body);
    return response.data;
  } catch (e) {
    console.error("POST ERROR:", e.message);

    if (e?.response?.status === 401) {
      return {
        data: [],
        message: "Mobile No or EmailId Already Exist...",
        status: false,
      };
    }

    return {
      data: [],
      message: "Server error, please try again...",
      status: false,
    };
  }
}

// ✅ IMAGE HELPER (🔥 MOST IMPORTANT)
function getImageUrl(imageName, ...fallbackHints) {
  const normalizedImageName = normalizeImageName(imageName);

  if (!normalizedImageName) {
    return getFallbackImage(...fallbackHints);
  }

  if (/^https?:\/\//i.test(normalizedImageName)) {
    return normalizedImageName;
  }

  const mappedImage = localImageMap[normalizedImageName.toLowerCase()];
  if (mappedImage) {
    return mappedImage;
  }

  return `${serverURL}/images/${encodeImagePath(normalizedImageName)}`;
}

function handleImageError(event, ...fallbackHints) {
  const fallbackImage = getFallbackImage(...fallbackHints);

  if (event?.currentTarget?.src !== fallbackImage) {
    event.currentTarget.src = fallbackImage;
  }
}

export {
  serverURL,
  getData,
  postData,
  generateOtp,
  getImageUrl,
  getImageList,
  pickImageName,
  handleImageError,
};
